    d,q,s=prepare_partial('FINAL_JOURNAL_MISMATCH');r=s.finish('INTERRUPTED');path=next((d/'wire').glob('*.jsonl'));original=r['durable_journal_hashes'][path.relative_to(d).as_posix()]
    with path.open('a',encoding='utf-8') as f:f.write('corrupt_final_journal\n')
    detected=sha(path.read_bytes())!=original;script=Script({});err=None
